/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Candidate
 *   Functions: release, key, comparison, candidate, group, view, applied, mount
 * Tests
 *   - the folded list gives each release its status, label, date and track count, and says how a non-matching one differs
 *   - the tie view repeats only the values that differ, here the disc and track order, and needs one release or none
 *   - the release applied for this run is marked and cannot be chosen again, an applied none disables none, and an earlier run's choice marks nothing
 *   - files whose duration or disc number is unknown are disclosed beside the releases, never counted as agreement, and nothing is said while all are known
 *   - one matching group of a partial comparison is offered in a region with the single-choice heading, every proposal value and Use none of these; the partial-comparison line is shown
 *   - a release applied as a preselection stays choosable when a re-rank leaves a tie, so it can be confirmed as the choice
 *   - a tie from a partial comparison keeps the several-releases heading and says not every release was compared; without a choice the line stands beside the folded list
 *   - groups that differ only by the MusicBrainz artist or label they credit show each ID beside the names
 * @end-catalog */

import { cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import { CandidateChooser } from './CandidateChooser';
import type { ImportLookupView } from './importLookupApi';

/**
 * The candidate chooser on its own: each candidate's status line and differences in the folded list, which values the tie view
 * repeats, how the applied release and an applied none are marked, the disclosure of files whose duration or disc number is
 * unknown, the optional choice a lone matching release of a partial comparison offers and where a partial comparison is said. All
 * names and identifiers are synthetic.
 */
type Candidate = ImportLookupView['candidates'][number];
const release = (n: number) => `0000000b-0000-4000-8000-00000000000${n}`;
const key = (n: number) => `musicbrainz:${release(n)}`;
const comparison = (differences: ('trackCount' | 'discCount' | 'duration')[] = []) => ({ trackCount: { local: 2, candidate: 2 }, discCount: { local: null, candidate: 2 }, differences, unknownLocalDurations: 0, unknownCandidateDurations: 0 });
const candidate = (n: number, extra: Partial<Candidate> = {}): Candidate => ({ key: key(n), releaseId: release(n), status: 'matching', title: `Synthetic Album ${n}`, artist: 'Synthetic Lead', label: `Label ${n}`,
  catalogNumber: null, barcode: null, country: null, date: { year: 2021, month: 5, day: null }, formats: [], trackCount: 2, comparison: comparison(), groupKey: String(n).repeat(64), artistMismatch: false, ...extra });
const group = (n: number, tracks: [number, number, string][]) => ({ groupKey: String(n).repeat(64), representativeKey: key(n), memberKeys: [key(n)], proposal: { albumTitle: 'Synthetic Album',
  artists: [{ name: 'Synthetic Lead', role: 'primary' as const, joinPhrase: null, musicBrainzId: null as string | null }], label: 'Label', labelMusicBrainzId: null as string | null, releaseDate: null, tracks: tracks.map(([discNumber, trackNumber, title]) => ({ discNumber, trackNumber, title })) } });
const view = (extra: Partial<ImportLookupView> = {}): ImportLookupView => ({ run: 2, state: 'complete', issue: null, outcome: 'candidates', input: { trigger: 'tags', submitted: null }, candidates: [], groups: [],
  preselection: null, disclosure: null, applied: null, staleFiles: [], needsAnswer: { tie: false, conflicts: [] }, blocking: false, ...extra });
const applied = (run: number, candidateKey: string | null): ImportLookupView['applied'] => ({ run, candidateKey, releaseId: null, choice: candidateKey ? 'chosen' : 'none', basis: candidateKey ? 'chosen' : null, values: [], conflicts: [], flagged: [] });
function mount(lookup: ImportLookupView, disabled = false) { const onChoose = vi.fn(); render(<CandidateChooser lookup={lookup} disabled={disabled} onChoose={onChoose} />); return onChoose; }
afterEach(cleanup);

test('the folded list gives each release its status, label, date and track count, and says how a non-matching one differs', () => {
  mount(view({ candidates: [candidate(1), candidate(2, { status: 'notMatching', groupKey: null, comparison: comparison(['discCount', 'duration']) }), candidate(3, { status: 'incomplete', label: null, date: null, trackCount: null, comparison: null }),
    candidate(4, { status: 'unverified', title: null, artist: null })] }));
  const [matching, differing, incomplete, unverified] = screen.getAllByRole('listitem').filter(item => item.querySelector('strong'));
  expect(within(matching).getByText('Matches these files · Label 1 · 2021-05 · 2 tracks')).toBeInTheDocument();
  expect(within(differing).getAllByRole('listitem').map(item => item.textContent)).toEqual(['Discs: — here, 2 on the release', 'Track durations differ']);
  expect(within(incomplete).getByText(/^Details could not be fetched/)).toBeInTheDocument();
  expect(unverified.querySelector('strong')!.textContent).toBe('—');
  expect(within(unverified).getByText(/^Not verified: some durations are unknown/)).toBeInTheDocument();
  // Missing evidence reads as a dash, never as an empty cell.
  expect([...matching.querySelectorAll('dd')].map(value => value.textContent)).toEqual(['—', '—', '—', '—']);
});

test('the tie view repeats only the values that differ, here the disc and track order, and needs one release or none', () => {
  const onChoose = mount(view({ candidates: [candidate(1), candidate(2)], groups: [group(1, [[1, 1, 'First'], [1, 2, 'Second']]), group(2, [[1, 1, 'First'], [2, 1, 'Second']])], needsAnswer: { tie: true, conflicts: [] } }));
  const tie = screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  const [first, second] = within(tie).getAllByRole('listitem');
  expect([...first.querySelectorAll('dt')].map(term => term.textContent)).toEqual(['Disc and track order', 'Barcode', 'Catalogue number', 'Country', 'Medium']);
  expect(second.querySelector('dd')!.textContent).toBe('1.1 First · 2.1 Second');
  // Each choice names the release it chooses.
  expect(within(second).getByRole('button', { name: 'Use this release' })).toHaveAccessibleDescription('Synthetic Album 2 · Synthetic Lead');
  fireEvent.click(within(tie).getByRole('button', { name: 'Use none of these' }));
  expect(onChoose).toHaveBeenCalledWith(null);
});

test('the release applied for this run is marked and cannot be chosen again, an applied none disables none, and an earlier run\'s choice marks nothing', () => {
  let onChoose = mount(view({ candidates: [candidate(1), candidate(2)], applied: applied(2, key(1)) }));
  expect(screen.getByRole('button', { name: 'Applied' })).toBeDisabled();
  fireEvent.click(screen.getByRole('button', { name: 'Use this release' })); expect(onChoose).toHaveBeenCalledWith(key(2));
  expect(screen.getByRole('button', { name: 'Use none of these' })).toBeEnabled();
  cleanup();
  mount(view({ candidates: [candidate(1)], applied: applied(2, null) }));
  expect(screen.getByRole('button', { name: 'Use none of these' })).toBeDisabled();
  cleanup();
  onChoose = mount(view({ candidates: [candidate(1)], applied: applied(1, key(1)) }));
  expect(screen.queryByRole('button', { name: 'Applied' })).not.toBeInTheDocument();
  fireEvent.click(screen.getByRole('button', { name: 'Use this release' })); expect(onChoose).toHaveBeenCalledWith(key(1));
  cleanup();
  mount(view({ candidates: [candidate(1)] }), true);
  for (const button of screen.getAllByRole('button')) expect(button).toBeDisabled();
});

test('files whose duration or disc number is unknown are disclosed beside the releases, never counted as agreement, and nothing is said while all are known', () => {
  mount(view({ candidates: [candidate(1)], disclosure: { unknownLocalDurations: 2, unknownLocalDiscNumbers: 1, partialComparison: false } }));
  expect(screen.getByText('Files with an unknown duration: 2. They are not counted as agreeing with any release.')).toBeInTheDocument();
  expect(screen.getByText('Files with an unknown disc number: 1. They are not counted as agreeing with any release.')).toBeInTheDocument();
  cleanup();
  // A tie shows the disclosure where the choice is made.
  mount(view({ candidates: [candidate(1), candidate(2)], groups: [group(1, [[1, 1, 'First']]), group(2, [[1, 1, 'Other']])], needsAnswer: { tie: true, conflicts: [] }, disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 3, partialComparison: false } }));
  const tie = screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  expect(within(tie).getByText('Files with an unknown disc number: 3. They are not counted as agreeing with any release.')).toBeInTheDocument();
  expect(screen.queryByText(/unknown duration/)).not.toBeInTheDocument();
  cleanup();
  for (const disclosure of [null, { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: false }]) {
    mount(view({ candidates: [candidate(1)], disclosure }));
    expect(screen.queryByText(/not counted as agreeing/)).not.toBeInTheDocument();
    cleanup();
  }
});

test('one matching group of a partial comparison is offered in a region with the single-choice heading, every proposal value and Use none of these; the partial-comparison line is shown', () => {
  const onChoose = mount(view({ candidates: [candidate(1), candidate(2, { status: 'notMatching', groupKey: null, comparison: comparison(['duration']) })], groups: [group(1, [[1, 1, 'First'], [1, 2, 'Second']])],
    disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true } }));
  const choice = screen.getByRole('region', { name: 'One release matches these files but was not applied, because not every release MusicBrainz found was compared. You can choose it, another release or none.' });
  expect(screen.getAllByRole('button', { name: 'Use none of these' })).toHaveLength(1);
  const [only] = within(choice).getAllByRole('listitem');
  // A single group shows every value it would write, since nothing differs from another group.
  expect([...only.querySelectorAll('dt')].map(term => term.textContent)).toEqual(['Title', 'Artists', 'Label', 'Release date', 'Disc and track order', 'Barcode', 'Catalogue number', 'Country', 'Medium']);
  expect(within(choice).getByText('Not every release MusicBrainz found was compared with these files, so a matching release may be missing from this list.')).toBeInTheDocument();
  fireEvent.click(within(only).getByRole('button', { name: 'Use this release' }));
  fireEvent.click(within(choice).getByRole('button', { name: 'Use none of these' }));
  expect(onChoose.mock.calls).toEqual([[key(1)], [null]]);
  cleanup();
  // A complete comparison says nothing about it.
  mount(view({ candidates: [candidate(1)], disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: false } }));
  expect(screen.queryByText(/not every release MusicBrainz found/i)).not.toBeInTheDocument();
  cleanup();
  // Once a release or none is applied for this run, nothing is offered: the release is marked in the folded list.
  for (const [choice, candidateKey] of [['chosen', key(1)], ['none', null]] as const) {
    mount(view({ candidates: [candidate(1)], groups: [group(1, [[1, 1, 'First']])], applied: { ...applied(2, candidateKey)!, choice }, disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true } }));
    expect(screen.queryByRole('region')).not.toBeInTheDocument();
    cleanup();
  }
});

test('a release applied as a preselection stays choosable when a re-rank leaves a tie, so it can be confirmed as the choice', () => {
  const onChoose = mount(view({ candidates: [candidate(1), candidate(2)], groups: [group(1, [[1, 1, 'First']]), group(2, [[1, 1, 'Other']])], needsAnswer: { tie: true, conflicts: [] },
    applied: { ...applied(2, key(1))!, choice: 'preselected', basis: 'onlyMatchingGroup' }, disclosure: { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true } }));
  const tie = screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  const [first] = within(tie).getAllByRole('listitem');
  expect(within(first).getByRole('button', { name: 'Use this release' })).toBeEnabled();
  fireEvent.click(within(first).getByRole('button', { name: 'Use this release' }));
  expect(onChoose).toHaveBeenCalledWith(key(1));
  expect(screen.queryByRole('button', { name: 'Applied' })).not.toBeInTheDocument();
});

test('a tie from a partial comparison keeps the several-releases heading and says not every release was compared; without a choice the line stands beside the folded list', () => {
  const partial = { unknownLocalDurations: 0, unknownLocalDiscNumbers: 0, partialComparison: true };
  const line = 'Not every release MusicBrainz found was compared with these files, so a matching release may be missing from this list.';
  mount(view({ candidates: [candidate(1), candidate(2)], groups: [group(1, [[1, 1, 'First']]), group(2, [[1, 1, 'Other']])], needsAnswer: { tie: true, conflicts: [] }, disclosure: partial }));
  const tie = screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' });
  expect(within(tie).getByText(line)).toBeInTheDocument();
  expect(screen.queryByRole('region', { name: /^One release matches/ })).not.toBeInTheDocument();
  cleanup();
  // A release applied by its shared identifier needs no choice, and the partial comparison is still said.
  mount(view({ candidates: [candidate(1)], groups: [group(1, [[1, 1, 'First']])], preselection: { candidateKey: key(1), basis: 'releaseId', artistMismatch: false },
    applied: { ...applied(2, key(1))!, choice: 'preselected', basis: 'releaseId' }, disclosure: partial }));
  expect(screen.queryByRole('region')).not.toBeInTheDocument();
  expect(screen.getByText(line)).toBeInTheDocument();
  expect(screen.getByRole('button', { name: 'Applied' })).toBeDisabled();
});

test('groups that differ only by the MusicBrainz artist or label they credit show each ID beside the names', () => {
  const id = (n: number) => `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`, tracks: [number, number, string][] = [[1, 1, 'First'], [1, 2, 'Second']];
  const credited = (n: number, artist: string, label: string) => { const value = group(n, tracks); value.proposal.artists = value.proposal.artists.map(entry => ({ ...entry, musicBrainzId: artist })); value.proposal.labelMusicBrainzId = label; return value; };
  mount(view({ candidates: [candidate(1), candidate(2)], groups: [credited(1, id(1), id(9)), credited(2, id(2), id(9))], needsAnswer: { tie: true, conflicts: [] } }));
  const [first, second] = within(screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' })).getAllByRole('listitem');
  expect([...first.querySelectorAll('dt')].map(term => term.textContent)[0]).toBe('Artists');
  expect(first.querySelector('dd')!.textContent).toBe(`Synthetic Lead · MusicBrainz ID ${id(1)}`);
  expect(second.querySelector('dd')!.textContent).toBe(`Synthetic Lead · MusicBrainz ID ${id(2)}`);
  cleanup();
  mount(view({ candidates: [candidate(1), candidate(2)], groups: [credited(1, id(1), id(8)), credited(2, id(1), id(9))], needsAnswer: { tie: true, conflicts: [] } }));
  const [labelled] = within(screen.getByRole('region', { name: 'Several releases match these files. Choose one, or none.' })).getAllByRole('listitem');
  expect(labelled.querySelector('dd')!.textContent).toBe(`Label · MusicBrainz ID ${id(8)}`);
});
